<?php
declare(strict_types=1);
require __DIR__ . '/../config/config.php';
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
$action=$_GET['action']??'view';
if($_SERVER['REQUEST_METHOD']==='POST' && $action==='receive'){
 $medicineId=(int)($_POST['medicine_id']??0);$boxes=max(0,(int)($_POST['boxes']??0));$strips=max(0,(int)($_POST['strips']??0));$units=max(0,(int)($_POST['units']??0));$batch=trim($_POST['batch_no']??'');$expiry=trim($_POST['expiry_date']??'')?:null;
 $m=db()->prepare('SELECT * FROM medicines WHERE id=? AND active=1');$m->execute([$medicineId]);$medicine=$m->fetch();
 if(!$medicine)exit('Medicine not found.');
 $total=$boxes*(int)$medicine['strips_per_box']*(int)$medicine['units_per_strip']+$strips*(int)$medicine['units_per_strip']+$units;
 if($total<1)exit('Enter at least one box, strip, or tablet.');
 $s=db()->prepare('INSERT INTO batches (medicine_id,batch_no,expiry_date,units_received,units_remaining,purchase_unit_cost) VALUES (?,?,?,?,?,?)');
 $s->execute([$medicineId,$batch?:null,$expiry,$total,$total,max(0,(float)($_POST['purchase_unit_cost']??0))]);$bid=(int)db()->lastInsertId();
 db()->prepare('INSERT INTO stock_movements (medicine_id,batch_id,movement_type,quantity_units,note) VALUES (?,?,"purchase",?,?)')->execute([$medicineId,$bid,$total,'Stock received']);
 header('Location: inventory.php?saved=1');exit;
}
$meds=db()->query('SELECT id,name,units_per_strip,strips_per_box FROM medicines WHERE active=1 ORDER BY name')->fetchAll();
$rows=db()->query('SELECT m.id,m.name,m.units_per_strip,m.strips_per_box,m.reorder_level,COALESCE(SUM(b.units_remaining),0) stock FROM medicines m LEFT JOIN batches b ON b.medicine_id=m.id WHERE m.active=1 GROUP BY m.id ORDER BY m.name')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventory · <?=h(APP_NAME)?></title><link rel="stylesheet" href="style.css"><style>.medicine-search-wrap{position:relative}.medicine-search{width:100%;box-sizing:border-box}.medicine-results{position:absolute;z-index:20;left:0;right:0;top:100%;background:#fff;border:1px solid #dfe5ef;border-radius:12px;box-shadow:0 12px 28px rgba(20,33,61,.14);overflow:hidden;display:none;max-height:260px;overflow-y:auto}.medicine-result{display:block;width:100%;border:0;background:#fff;text-align:left;padding:12px 14px;cursor:pointer;border-bottom:1px solid #edf0f5}.medicine-result:hover{background:#f4f7ff}.medicine-result strong{display:block}.medicine-result small{color:#718096}.selected-medicine{display:none;margin-top:8px;padding:10px 12px;border-radius:10px;background:#eef5ff;color:#294b86}.selected-medicine button{float:right;border:0;background:transparent;color:#294b86;cursor:pointer;font-weight:700}</style></head><body><header><div class="brand">💊 <?=h(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a class="active" href="manage.php">Management</a></nav><div class="user-info">👤 <?=h(current_user()['username']??'')?> · <?=h(ucfirst(current_user()['role']??''))?> · <a href="logout.php">Logout</a></div></header><main><div class="page-title"><div><div class="eyebrow">STOCK CONTROL</div><h1>Inventory</h1><p>Search for a medicine instead of selecting from a long list.</p></div></div><?php if(isset($_GET['saved'])):?><div class="success">✓ Stock received successfully.</div><?php endif;?><section class="panel"><h2>Receive Stock</h2><form method="post" action="inventory.php?action=receive" class="grid"><div class="medicine-search-wrap"><label>Search Medicine *</label><input class="medicine-search" id="medicineSearch" type="text" autocomplete="off" placeholder="Type medicine name..."><div class="medicine-results" id="medicineResults"></div><div class="selected-medicine" id="selectedMedicine"><span id="selectedText"></span><button type="button" id="clearMedicine">Change</button></div><input type="hidden" name="medicine_id" id="medicineId" required></div><label>Batch Number <span class="optional">(optional)</span><input name="batch_no" placeholder="Leave blank if not available"></label><label>Expiry Date <span class="optional">(optional)</span><input type="date" name="expiry_date"></label><label>Boxes<input type="number" name="boxes" min="0" value="0"></label><label>Strips<input type="number" name="strips" min="0" value="0"></label><label>Loose Tablets<input type="number" name="units" min="0" value="0"></label><label>Purchase Cost / Tablet<input type="number" step="0.0001" name="purchase_unit_cost" min="0" value="0"></label><button class="btn">Receive Stock</button></form></section><section class="panel"><h2>Current Stock</h2><table><tr><th>Medicine</th><th>Pack</th><th>Stock</th><th>Reorder</th></tr><?php foreach($rows as $r):?><tr><td><b><?=h($r['name'])?></b></td><td><?=$r['units_per_strip']?> tablets/strip × <?=$r['strips_per_box']?> strips/box</td><td><b><?=number_format((int)$r['stock'])?></b> tablets</td><td><?=number_format((int)$r['reorder_level'])?></td></tr><?php endforeach;?></table></section></main><script>const medicines=<?=json_encode($meds,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>;const search=document.getElementById('medicineSearch'),results=document.getElementById('medicineResults'),id=document.getElementById('medicineId'),selected=document.getElementById('selectedMedicine'),selectedText=document.getElementById('selectedText'),clear=document.getElementById('clearMedicine');function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}function choose(m){id.value=m.id;selectedText.textContent=m.name+' · '+m.units_per_strip+'/strip · '+m.strips_per_box+' strips/box';selected.style.display='block';search.style.display='none';results.style.display='none';}function render(){const q=search.value.trim().toLowerCase();if(!q){results.style.display='none';return}const found=medicines.filter(m=>m.name.toLowerCase().includes(q)).slice(0,20);results.innerHTML=found.length?found.map(m=>'<button type="button" class="medicine-result" data-id="'+m.id+'"><strong>'+esc(m.name)+'</strong><small>'+m.units_per_strip+'/strip · '+m.strips_per_box+' strips/box</small></button>').join(''):'<div class="medicine-result">No medicine found.</div>';results.style.display='block';results.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>choose(medicines.find(m=>m.id==b.dataset.id)));}search.addEventListener('input',render);search.addEventListener('focus',render);clear.onclick=()=>{id.value='';selected.style.display='none';search.style.display='block';search.value='';search.focus();};document.addEventListener('click',e=>{if(!e.target.closest('.medicine-search-wrap'))results.style.display='none';});</script></body></html>